const items = $input.all();
const outputItems = [];

for (const item of items) {
  const rawName = item.json.customer_name || '';
  const rawDate = item.json.order_date || '';

  // 1. 字串清理
  const cleanName = rawName.trim().replace(/\s*\(VIP\)/g, '');

  // 2. 正規表達式替換日期符號
  const isoDate = rawDate.replace(/\//g, '-');
  const dateObj = new Date(isoDate);

  // 3. 繁體中文語系格式化
  const twDate = dateObj.toLocaleDateString('zh-TW', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });

  outputItems.push({
    json: {
      customer_name_original: rawName,
      customer_name_clean: cleanName,
      amount: Number(item.json.amount) || 0,
      order_date_original: rawDate,
      order_date_iso: isoDate,
      formatted_date_tw: twDate
    }
  });
}

return outputItems;
